                'css'      => '@import url(\'https://fonts.googleapis.com/css2?family=Barlow+Condensed:ital,wght@0,400;0,600;0,700;0,800;1,700&family=Barlow:wght@400;500;600&display=swap\');*{margin:0;padding:0;box-sizing:border-box}:root{--orange:#f7971e;--dark:#0d0d0d;--text:#fff}body{font-family:"Barlow",sans-serif;background:var(--dark);color:var(--text);line-height:1.6}.gym-nav{display:flex;justify-content:space-between;align-items:center;padding:1.2rem 6%;position:sticky;top:0;background:rgba(13,13,13,.95);backdrop-filter:blur(10px);z-index:100;border-bottom:1px solid #222}.gym-logo{font-family:"Barlow Condensed",sans-serif;font-size:1.8rem;font-weight:800;letter-spacing:.05em;color:#fff}.gym-logo span{color:var(--orange)}.gym-menu a{color:#aaa;text-decoration:none;margin-left:2rem;font-weight:500;font-size:.95rem;transition:.2s}.gym-menu a:hover{color:#fff}.gym-cta{background:var(--orange)!important;color:var(--dark)!important;padding:.5rem 1.2rem!important;border-radius:4px!important;font-weight:700!important}.gym-hero{min-height:90vh;background:linear-gradient(rgba(0,0,0,.6),rgba(0,0,0,.8)),linear-gradient(135deg,#1a1a2e,#16213e);display:flex;align-items:center;padding:0 6%;position:relative;overflow:hidden}.gym-hero::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 70% 50%,rgba(247,151,30,.1) 0%,transparent 70%)}.gym-hero-content{position:relative;max-width:650px}.gym-label{color:var(--orange);font-size:.8rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;margin-bottom:1.5rem;display:block}.gym-hero h1{font-family:"Barlow Condensed",sans-serif;font-size:6rem;font-weight:800;line-height:.95;text-transform:uppercase;font-style:italic;margin-bottom:1.5rem}.gym-hero p{color:rgba(255,255,255,.7);font-size:1.1rem;margin-bottom:2.5rem;max-width:500px}.gym-btns{display:flex;gap:1rem}.g-btn-primary{background:var(--orange);color:var(--dark);text-decoration:none;padding:1rem 2rem;font-weight:700;font-size:.95rem;text-transform:uppercase;letter-spacing:.05em;transition:.2s}.g-btn-primary:hover{background:#e8891a}.g-btn-ghost{color:#fff;text-decoration:none;padding:1rem 2rem;border:1px solid rgba(255,255,255,.3);font-weight:500;transition:.2s}.g-btn-ghost:hover{border-color:var(--orange);color:var(--orange)}.gym-stats{display:grid;grid-template-columns:repeat(4,1fr);background:#111;border-top:3px solid var(--orange)}.g-stat{padding:2rem;text-align:center;border-right:1px solid #222}.g-stat:last-child{border-right:none}.g-num{display:block;font-family:"Barlow Condensed",sans-serif;font-size:2.5rem;font-weight:800;color:var(--orange)}.g-label{color:#666;font-size:.85rem;margin-top:.3rem;display:block}.gym-classes{padding:6rem 6%}.gym-classes h2{font-family:"Barlow Condensed",sans-serif;font-size:3rem;font-weight:800;text-transform:uppercase;font-style:italic;margin-bottom:3rem}.classes-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1.5rem}.class-card{background:#111;border-radius:12px;overflow:hidden;transition:.3s}.class-card:hover{transform:translateY(-4px)}.class-img{height:200px;display:flex;align-items:flex-end;padding:1rem}.class-name{font-family:"Barlow Condensed",sans-serif;font-size:1.5rem;font-weight:800;text-transform:uppercase;font-style:italic;color:#fff}.class-info{padding:1.2rem}.class-level{font-size:.75rem;color:var(--orange);font-weight:700;text-transform:uppercase;letter-spacing:.1em;display:block;margin-bottom:.5rem}.class-info p{color:#aaa;font-size:.85rem;margin-bottom:.5rem}.class-time{font-size:.75rem;color:#666;display:block}.gym-pricing{padding:6rem 6%;background:#111}.gym-pricing h2{font-family:"Barlow Condensed",sans-serif;font-size:3rem;font-weight:800;text-transform:uppercase;font-style:italic;text-align:center;margin-bottom:3rem}.gym-plans{display:grid;grid-template-columns:repeat(3,1fr);gap:2rem;max-width:900px;margin:0 auto}.gym-plan{background:#1a1a1a;border:1px solid #222;border-radius:12px;padding:2.5rem;text-align:center;position:relative}.gym-plan.popular{border-color:var(--orange)}.pop-badge{position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--orange);color:var(--dark);font-size:.75rem;font-weight:700;padding:.3rem 1rem;border-radius:20px}.gym-plan h3{font-family:"Barlow Condensed",sans-serif;font-size:1.5rem;font-weight:700;text-transform:uppercase;margin-bottom:1rem;color:#aaa}.gym-price{font-family:"Barlow Condensed",sans-serif;font-size:3.5rem;font-weight:800;color:var(--orange);margin-bottom:1.5rem}.gym-price span{font-size:1rem;color:#666}.gym-plan ul{list-style:none;text-align:left;margin-bottom:2rem}.gym-plan li{color:#aaa;font-size:.9rem;padding:.4rem 0;border-bottom:1px solid #222}.plan-btn{display:block;border:2px solid var(--orange);color:var(--orange);text-decoration:none;padding:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;transition:.2s}.plan-btn:hover{background:var(--orange);color:var(--dark)}.plan-btn-dark{display:block;background:var(--orange);color:var(--dark);text-decoration:none;padding:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;transition:.2s}.gym-footer{text-align:center;padding:1.5rem;background:#080808;color:#444;font-size:.8rem}@media(max-width:768px){.gym-hero h1{font-size:4rem}.classes-grid{grid-template-columns:1fr 1fr}.gym-plans{grid-template-columns:1fr}.gym-stats{grid-template-columns:1fr 1fr}}',
                'js'       => '',
            ],
        ];

        // Create 14 more simplified but functional templates
        $moreTemplates = [
            ['name' => 'Blog Personal', 'category' => 'Blog', 'tags' => ['blog', 'escritura', 'personal']],
            ['name' => 'CV/Resume', 'category' => 'Portfolio', 'tags' => ['cv', 'resume', 'profesional']],
            ['name' => 'Boda', 'category' => 'Evento', 'tags' => ['boda', 'romántico', 'RSVP']],
            ['name' => 'Tienda Online', 'category' => 'E-commerce', 'tags' => ['tienda', 'productos', 'ventas']],
            ['name' => 'Inmobiliaria', 'category' => 'Inmobiliaria', 'tags' => ['propiedades', 'real estate', 'vivienda']],
            ['name' => 'Clínica/Salud', 'category' => 'Salud', 'tags' => ['clínica', 'médico', 'salud']],
            ['name' => 'Abogado/Consultoría', 'category' => 'Consultoría', 'tags' => ['abogado', 'legal', 'consultoría']],
            ['name' => 'Startup Tech', 'category' => 'SaaS', 'tags' => ['startup', 'tech', 'inversores']],
            ['name' => 'Fotógrafo', 'category' => 'Portfolio', 'tags' => ['fotografía', 'galería', 'fotos']],
            ['name' => 'Músico/Artista', 'category' => 'Artista', 'tags' => ['música', 'artista', 'conciertos']],
            ['name' => 'ONG/Fundación', 'category' => 'ONG', 'tags' => ['ong', 'donaciones', 'causas']],
            ['name' => 'Ecommerce Moda', 'category' => 'E-commerce', 'tags' => ['moda', 'ropa', 'fashion']],
            ['name' => 'Evento/Conferencia', 'category' => 'Evento', 'tags' => ['evento', 'conferencia', 'speakers']],
            ['name' => 'Peluquería/Beauty', 'category' => 'Belleza', 'tags' => ['peluquería', 'belleza', 'salon']],
        ];

        $gradients = [
            ['#667eea', '#764ba2'], ['#f093fb', '#f5576c'], ['#4facfe', '#00f2fe'],
            ['#43e97b', '#38f9d7'], ['#fa709a', '#fee140'], ['#a18cd1', '#fbc2eb'],
            ['#ffecd2', '#fcb69f'], ['#ff9a9e', '#fecfef'], ['#a1c4fd', '#c2e9fb'],
            ['#d4fc79', '#96e6a1'], ['#89f7fe', '#66a6ff'], ['#fddb92', '#d1fdff'],
            ['#e0c3fc', '#8ec5fc'], ['#f6d365', '#fda085'],
        ];

        foreach ($moreTemplates as $i => $t) {
            $g = $gradients[$i];
            $templates[] = array_merge($t, [
                'html' => $this->generateBaseHtml($t['name'], $g[0], $g[1]),
                'css'  => $this->generateBaseCss($g[0], $g[1]),
                'js'   => '',
            ]);
        }

        foreach ($templates as $template) {
            Template::create($template);
        }
    }

    private function generateBaseHtml(string $name, string $c1, string $c2): string
    {
        $slug = strtolower(str_replace([' ', '/'], ['-', ''], $name));
        return "<nav class=\"nav-{$slug}\"><div class=\"logo\">{$name}</div><div class=\"nav-links\"><a href=\"#\">Inicio</a><a href=\"#\">Servicios</a><a href=\"#\">Contacto</a><a href=\"#\" class=\"nav-cta\">Empezar</a></div></nav><section class=\"hero-{$slug}\"><div class=\"hero-content\"><h1>Bienvenido a {$name}</h1><p>Describe aquí tu propuesta de valor principal. Qué haces, para quién y por qué eres diferente.</p><a href=\"#\" class=\"cta-btn\">Comenzar ahora</a></div></section><section class=\"features\"><h2>Nuestros servicios</h2><div class=\"feat-grid\"><div class=\"feat-card\"><div class=\"feat-icon\">⭐</div><h3>Servicio Premium</h3><p>Descripción del primer servicio o característica destacada.</p></div><div class=\"feat-card\"><div class=\"feat-icon\">🚀</div><h3>Rápido y eficiente</h3><p>Descripción del segundo servicio o característica.</p></div><div class=\"feat-card\"><div class=\"feat-icon\">🛡️</div><h3>Confianza total</h3><p>Descripción del tercer servicio o característica.</p></div></div></section><section class=\"cta-section\"><h2>¿Listo para empezar?</h2><p>Únete a miles de clientes satisfechos</p><a href=\"#\" class=\"cta-main\">Contáctanos hoy</a></section><footer class=\"footer\"><p>© 2024 {$name} · Todos los derechos reservados</p></footer>";
    }

    private function generateBaseCss(string $c1, string $c2): string
    {
        return "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');*{margin:0;padding:0;box-sizing:border-box}:root{--c1:{$c1};--c2:{$c2}}body{font-family:Inter,sans-serif;line-height:1.6}nav{display:flex;justify-content:space-between;align-items:center;padding:1rem 5%;background:#fff;border-bottom:1px solid #eee;position:sticky;top:0;z-index:100}.logo{font-weight:800;font-size:1.2rem;background:linear-gradient(135deg,var(--c1),var(--c2));-webkit-background-clip:text;-webkit-text-fill-color:transparent}.nav-links a{color:#666;text-decoration:none;margin-left:1.5rem;font-size:.9rem}.nav-cta{background:linear-gradient(135deg,var(--c1),var(--c2));color:#fff!important;padding:.5rem 1.2rem;border-radius:6px;font-weight:600}section[class*=hero]{padding:6rem 5%;background:linear-gradient(135deg,var(--c1),var(--c2));text-align:center;color:#fff;min-height:60vh;display:flex;align-items:center;justify-content:center}.hero-content h1{font-size:3rem;font-weight:800;margin-bottom:1.5rem}.hero-content p{font-size:1.1rem;opacity:.9;margin-bottom:2rem;max-width:600px;margin-left:auto;margin-right:auto}.cta-btn{display:inline-block;background:#fff;color:#333;text-decoration:none;padding:.9rem 2rem;border-radius:8px;font-weight:700;font-size:.95rem}.features{padding:5rem 5%;text-align:center}.features h2{font-size:2rem;font-weight:800;margin-bottom:3rem}.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2rem;max-width:900px;margin:0 auto}.feat-card{padding:2rem;border-radius:12px;background:#f9fafb;transition:.3s}.feat-card:hover{transform:translateY(-4px);box-shadow:0 20px 40px rgba(0,0,0,.08)}.feat-icon{font-size:2rem;margin-bottom:1rem}.feat-card h3{font-weight:700;margin-bottom:.5rem}.feat-card p{color:#666;font-size:.9rem}.cta-section{padding:5rem;text-align:center;background:linear-gradient(135deg,var(--c1),var(--c2));color:#fff}.cta-section h2{font-size:2.5rem;font-weight:800;margin-bottom:1rem}.cta-section p{margin-bottom:2rem;opacity:.9}.cta-main{display:inline-block;background:#fff;color:#333;text-decoration:none;padding:1rem 2.5rem;border-radius:8px;font-weight:700;transition:.2s}.footer{text-align:center;padding:2rem;background:#111;color:#666;font-size:.85rem}@media(max-width:768px){.feat-grid{grid-template-columns:1fr}.hero-content h1{font-size:2rem}}";
    }
}
